import java.io.IOException;

import org.apache.accumulo.core.cli.ConfigOpts;
import org.apache.accumulo.manager.Manager;
import org.apache.accumulo.test.ample.metadata.FlakyAmpleServerContext;

/**
 * A {@link Manager} that uses a {@link FlakyAmpleServerContext} so that its conditional mutations of
 * tablet metadata have ambiguous (UNKNOWN) outcomes. Intended for use in testing only.
 */
public class FlakyAmpleManager extends Manager {

  public FlakyAmpleManager(ConfigOpts opts, String[] args) throws IOException {
    super(opts, FlakyAmpleServerContext::new, args);
  }

  public static void main(String[] args) throws Exception {
    try (FlakyAmpleManager manager = new FlakyAmpleManager(new ConfigOpts(), args)) {
      manager.runServer();
    }
  }
}
